using System.IO;
using System.Text;
namespace FaceAssets;
internal static class NifGuard {
 public static MemoryStream Open(string path){using var file=File.OpenRead(path);long length=file.Length;if(length<128||length>64*1024*1024)throw new InvalidDataException("NIF must be 128 B–64 MiB.");var bytes=new byte[checked((int)length)];file.ReadExactly(bytes);var snapshot=new MemoryStream(bytes,false);using var r=new BinaryReader(snapshot,Encoding.ASCII,true);string line="";for(int i=0;i<128;i++){byte b=r.ReadByte();if(b==10)break;line+=(char)b;}if(!line.StartsWith("Gamebryo File Format")||r.ReadUInt32()!=0x14020007||r.ReadByte()!=1||r.ReadUInt32()!=12)throw new InvalidDataException("Only little-endian Skyrim SE/AE 20.2.0.7 user 12 NIF is supported.");int blocks=r.ReadInt32();if(blocks<1||blocks>4096||r.ReadUInt32()!=100)throw new InvalidDataException("Only Skyrim stream 100 with 1–4096 blocks is supported.");void Skip(int count){if(count<0||count>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Truncated NIF.");r.BaseStream.Position+=count;}for(int i=0;i<3;i++)Skip(r.ReadByte());int types=r.ReadUInt16();if(types<1||types>512)throw new InvalidDataException("NIF block-type limit exceeded.");var names=new List<string>();for(int i=0;i<types;i++){int len=r.ReadInt32();if(len<1||len>128)throw new InvalidDataException("Invalid NIF block name.");names.Add(Encoding.ASCII.GetString(r.ReadBytes(len)));}var table=new ushort[blocks];for(int i=0;i<blocks;i++){table[i]=r.ReadUInt16();if(table[i]>=types)throw new InvalidDataException("Invalid NIF type index.");}var sizes=new int[blocks];long total=0;for(int i=0;i<blocks;i++){sizes[i]=r.ReadInt32();if(sizes[i]<0||sizes[i]>64*1024*1024)throw new InvalidDataException("Invalid NIF block size.");total+=sizes[i];}uint strings=r.ReadUInt32(),max=r.ReadUInt32();if(strings>65536||max>4096)throw new InvalidDataException("NIF string limit exceeded.");for(int i=0;i<strings;i++){int len=r.ReadInt32();if(len<0||len>4096)throw new InvalidDataException("Invalid NIF string.");Skip(len);}uint groups=r.ReadUInt32();if(groups>4096)throw new InvalidDataException("NIF group limit exceeded.");Skip(checked((int)groups*4));if(total>r.BaseStream.Length-r.BaseStream.Position-4)throw new InvalidDataException("Truncated NIF block table.");for(int i=0;i<blocks;i++){long at=r.BaseStream.Position;string type=names[table[i]];if(type=="NiSkinData"&&sizes[i]>=56){Skip(52);if(r.ReadUInt32()>256)throw new InvalidDataException("Excessive head skin bones.");}if(type=="BSShaderTextureSet"&&sizes[i]>=4&&r.ReadUInt32()>16)throw new InvalidDataException("Excessive texture slots.");r.BaseStream.Position=at+sizes[i];}uint roots=r.ReadUInt32();if(roots>4096||roots*4>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Invalid NIF root table.");snapshot.Position=0;return snapshot;}
}
